import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/installation.md","filePath":"de/guide/installation.md","lastUpdated":1793173149000}`),a={name:`de/guide/installation.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to “Installation”">​</a></h1><p>Sudoku ist als universelle App im App Store erhältlich und unterstützt iPhone, iPad und Mac mit einem einzigen Kauf.</p><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to “Download”">​</a></h2><ul><li><strong>App Store</strong>: <a href="https://apps.apple.com/app/id6793606018" target="_blank" rel="noreferrer">Sudoku herunterladen</a> — universelle App für iPhone, iPad &amp; Mac</li></ul><h3 id="app-store-empfohlen" tabindex="-1">App Store (empfohlen) <a class="header-anchor" href="#app-store-empfohlen" aria-label="Permalink to “App Store (empfohlen)”">​</a></h3><p>Die App-Store-Version bietet automatische Updates und eine nahtlose Integration in alle Ihre Apple-Geräte.</p><ul><li><strong>App Store ID</strong>: 6793606018</li><li><strong>Link</strong>: <a href="https://apps.apple.com/app/id6793606018" target="_blank" rel="noreferrer">https://apps.apple.com/app/id6793606018</a></li><li><strong>Plattformen</strong>: iPhone, iPad, Mac (universelle App)</li><li><strong>Preis</strong>: Die aktuellen Preise finden Sie im App-Store-Eintrag</li></ul><h2 id="installationsschritte" tabindex="-1">Installationsschritte <a class="header-anchor" href="#installationsschritte" aria-label="Permalink to “Installationsschritte”">​</a></h2><h3 id="iphone-ipad" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ol><li>Öffnen Sie den <strong>App Store</strong> auf Ihrem Gerät</li><li>Suchen Sie nach „Sudoku“ oder verwenden Sie den direkten Link oben</li><li>Tippen Sie auf <strong>Laden</strong> oder <strong>Kaufen</strong>, um die App herunterzuladen</li><li>Die App wird automatisch installiert</li><li>Starten Sie Sudoku über den Home-Bildschirm</li></ol><h3 id="mac" tabindex="-1">Mac <a class="header-anchor" href="#mac" aria-label="Permalink to “Mac”">​</a></h3><ol><li>Öffnen Sie den <strong>App Store</strong> auf Ihrem Mac</li><li>Suchen Sie nach „Sudoku“ oder verwenden Sie den direkten Link oben</li><li>Klicken Sie auf <strong>Laden</strong> oder <strong>Kaufen</strong>, um die App zu erwerben</li><li>Die App wird automatisch heruntergeladen und installiert</li><li>Starten Sie Sudoku aus dem Ordner „Programme“ oder über Launchpad</li></ol><h2 id="erster-start" tabindex="-1">Erster Start <a class="header-anchor" href="#erster-start" aria-label="Permalink to “Erster Start”">​</a></h2><p>Beim ersten Start von Sudoku fragt die App nach der Berechtigung für iCloud (Synchronisierung) und Game Center (Ranglisten und Erfolge). Beides ist optional – das Spiel funktioniert auch ohne vollständig offline.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to “Updates”">​</a></h2><p>Updates werden automatisch über den App Store bereitgestellt. Um manuell nach Updates zu suchen, öffnen Sie den App Store und wechseln Sie zum Bereich <strong>Account → Updates</strong>.</p><h2 id="deinstallation" tabindex="-1">Deinstallation <a class="header-anchor" href="#deinstallation" aria-label="Permalink to “Deinstallation”">​</a></h2><h3 id="iphone-ipad-1" tabindex="-1">iPhone / iPad <a class="header-anchor" href="#iphone-ipad-1" aria-label="Permalink to “iPhone / iPad”">​</a></h3><ol><li>Halten Sie das Sudoku-App-Symbol gedrückt</li><li>Tippen Sie auf <strong>App entfernen</strong> → <strong>App löschen</strong></li></ol><h3 id="mac-1" tabindex="-1">Mac <a class="header-anchor" href="#mac-1" aria-label="Permalink to “Mac”">​</a></h3><ol><li>Beenden Sie Sudoku</li><li>Ziehen Sie <code>Sudoku.app</code> aus <code>Applications</code> in den Papierkorb</li><li>(Optional) App-Daten entfernen:</li></ol><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><h2 id="systemanforderungen" tabindex="-1">Systemanforderungen <a class="header-anchor" href="#systemanforderungen" aria-label="Permalink to “Systemanforderungen”">​</a></h2><ul><li><strong>iPhone/iPad</strong>: iOS/iPadOS 16.0 oder neuer</li><li><strong>Mac</strong>: macOS 15.0 (Sequoia) oder neuer</li><li><strong>CPU</strong>: Apple Silicon (M-Serie)</li><li><strong>Arbeitsspeicher</strong>: mindestens 2 GB</li><li><strong>Speicherplatz</strong>: ca. 50 MB</li><li><strong>Netzwerk</strong>: für das Spielen nicht erforderlich (iCloud/Game Center optional)</li></ul><h2 id="problembehandlung" tabindex="-1">Problembehandlung <a class="header-anchor" href="#problembehandlung" aria-label="Permalink to “Problembehandlung”">​</a></h2><p>Falls bei der Installation Probleme auftreten:</p><ul><li><strong>macOS blockiert die App</strong>: Öffnen Sie <strong>Systemeinstellungen → Datenschutz &amp; Sicherheit</strong> und klicken Sie bei Sudoku auf <strong>Dennoch öffnen</strong></li><li><strong>App wird nicht angezeigt</strong>: Starten Sie den App Store oder Ihr Gerät neu und versuchen Sie es erneut</li></ul><p>Weitere Hilfe finden Sie in der <a href="./troubleshooting.html">Anleitung zur Problembehandlung</a> oder Sie eröffnen ein Issue im Projekt-Repository.</p>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};